import { useEffect, useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';

export function LogList() {
  const [rows, setRows] = useState([]);
  const parentRef = useRef(null);
  useEffect(() => {
    fetch('/api/logs?limit=5000').then((r) => r.json()).then(setRows);
  }, []);
  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 32,
  });
  return (
    <div ref={parentRef} className="log-list" style={{ height: 480, overflow: 'auto' }}>
      <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
        {virtualizer.getVirtualItems().map((item) => (
          <div key={item.key} className="log-row" style={{ position: 'absolute', top: item.start, height: item.size, width: '100%' }}>
            {rows[item.index].message}
          </div>
        ))}
      </div>
    </div>
  );
}
```

